import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.D9kpkP22.js";const u=JSON.parse('{"title":"Development","description":"","frontmatter":{},"headers":[],"relativePath":"temp/DEVELOPMENT.md","filePath":"temp/DEVELOPMENT.md"}'),l={name:"temp/DEVELOPMENT.md"};function r(s,e,n,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h1><p>Notes for building and working on Frost locally.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Java 21 (JDK)</li><li>Maven 3.9+</li><li>Paper 1.21.1+ test server</li></ul><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mvn</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span></span></code></pre></div><p>Artifacts are written to <code>target/</code> (e.g., <code>frost-1.0.0.jar</code>). The shade plugin relocates Gson into a private package to avoid conflicts.</p><h2 id="install-to-server" tabindex="-1">Install to Server <a class="header-anchor" href="#install-to-server" aria-label="Permalink to &quot;Install to Server&quot;">​</a></h2><ol><li>Copy the built jar into your server’s <code>plugins/</code> directory.</li><li>Start the server to generate <code>plugins/Frost/config.yml</code> and <code>plugins/Frost/database.db</code>.</li><li>Edit <code>config.yml</code>, then run <code>/frost reload</code> to apply changes.</li></ol><h2 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h2><ul><li>Core plugin entry: <code>com.stufy.fragmc.frost.Frost</code>.</li><li>Public API: <code>com.stufy.fragmc.frost.api.FrostAPI</code> (exposed via <code>Frost#getAPI()</code>).</li><li>Managers: configuration, profiles, cosmetics, particles, GUI, database, player data.</li><li>Resources: <code>plugin.yml</code>, <code>config.yml</code>.</li></ul><h2 id="testing-tips" tabindex="-1">Testing Tips <a class="header-anchor" href="#testing-tips" aria-label="Permalink to &quot;Testing Tips&quot;">​</a></h2><ul><li>Use a fresh test world and a clean <code>plugins/Frost/</code> folder for baseline behavior.</li><li>Exercise particle triggers: jump, sprint, sneak, glide, swim, damage, kill, block break/place.</li><li>Verify Hotbar Lock: enable with <code>/togglelock</code>, ensure locked slots resist edits/drops.</li><li>Check Bedrock UIs with Floodgate if available; otherwise Java inventory UIs are used.</li></ul><h2 id="coding-notes" tabindex="-1">Coding Notes <a class="header-anchor" href="#coding-notes" aria-label="Permalink to &quot;Coding Notes&quot;">​</a></h2><ul><li>Target API: Paper 1.21.1; compile level: Java 21.</li><li>Avoid logging secrets or writing sensitive data to disk.</li><li>Keep <code>provided</code> scope for server APIs; shade only what you must relocate.</li></ul>',15)])])}const g=a(l,[["render",r]]);export{u as __pageData,g as default};
